CREATE DATABASE IF NOT EXISTS mitra; USE mitra;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,display_name VARCHAR(120) NOT NULL,password_hash VARCHAR(255) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS posts(id BIGINT UNSIGNED PRIMARY KEY,author_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT fk_posts_author FOREIGN KEY(author_id) REFERENCES users(id),INDEX idx_posts_author_created(author_id,created_at DESC,id DESC));
CREATE TABLE IF NOT EXISTS follows(follower_id BIGINT UNSIGNED NOT NULL,following_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(follower_id,following_id),CONSTRAINT fk_follow_a FOREIGN KEY(follower_id) REFERENCES users(id),CONSTRAINT fk_follow_b FOREIGN KEY(following_id) REFERENCES users(id),CONSTRAINT chk_follow_self CHECK(follower_id<>following_id),INDEX idx_following(following_id,follower_id));
CREATE TABLE IF NOT EXISTS post_likes(user_id BIGINT UNSIGNED NOT NULL,post_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(user_id,post_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE IF NOT EXISTS comments(id BIGINT UNSIGNED PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,post_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES posts(id),INDEX idx_comments_post_created(post_id,created_at DESC,id DESC));
CREATE TABLE IF NOT EXISTS bookmarks(user_id BIGINT UNSIGNED NOT NULL,post_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(user_id,post_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(post_id) REFERENCES posts(id));
